-- =============================================================================
-- ERAM - Script de Carga Completa de TODOS los Productos
-- =============================================================================
-- Este script carga TODOS los 328 productos del catálogo ERAM
-- Generado automáticamente desde ERAM_Catalogo_Categorias_y_Productos.txt
-- =============================================================================


-- =============================================================================
-- ON CONFLICT para actualizar productos existentes
-- =============================================================================

ON CONFLICT (codigo) DO UPDATE SET
    categoria_id = EXCLUDED.categoria_id,
    subcategoria_id = EXCLUDED.subcategoria_id,
    nombre = EXCLUDED.nombre,
    descripcion = EXCLUDED.descripcion,
    medidas = EXCLUDED.medidas,
    presentacion = EXCLUDED.presentacion,
    moneda = EXCLUDED.moneda,
    precio_unitario = EXCLUDED.precio_unitario,
    precios_por_bulto = EXCLUDED.precios_por_bulto,
    fuente = EXCLUDED.fuente,
    notas = EXCLUDED.notas,
    updated_at = NOW();
